def __init__(self, arn: str, attached_policies: Optional[List[Policy]]):
    """Constructor"""
    if arn is None or not arns.get_resource(arn).startswith('group/'):
        raise ValueError('Group objects must be constructed with a valid ARN for a group')
    self.arn = arn

    if attached_policies is None:
        self.attached_policies = []
    else:
        self.attached_policies = attached_policies

def __init__(self, nodes: list = None, edges: list = None, policies: list = None, groups: list = None,
             metadata: dict = None):
    """Constructor"""
    for arg, value in {'nodes': nodes, 'edges': edges, 'policies': policies, 'groups': groups,
                       'metadata': metadata}.items():
        if value is None:
            raise ValueError('Required constructor argument {} was None'.format(arg))
    self.nodes = nodes
    self.edges = edges
    self.policies = policies
    self.groups = groups
    if 'account_id' not in metadata:
        raise ValueError('Incomplete metadata input, expected key: "account_id"')
    if 'pmapper_version' not in metadata:
        raise ValueError('Incomplete metadata input, expected key: "pmapper_version"')
    self.metadata = metadata

def __init__(self, account_id: str, scps: List[Policy], tags: Optional[dict]):
    self.account_id = account_id
    self.scps = scps
    if tags is None:
        self.tags = {}
    else:
        self.tags = tags

def to_dictionary(self) -> dict:
    """Returns a dictionary representation of this object for storage"""
    return {
        'arn': self.arn,
        'attached_policies': [{'arn': policy.arn, 'name': policy.name} for policy in self.attached_policies]
    }

def get_node_by_searchable_name(self, name: str) -> Optional[Node]:
    """Locates a node by a given searchable name, returns the Node or None"""
    for node in self.nodes:
        if node.searchable_name() == name:
            return node
    return None

def to_dictionary(self) -> dict:
    """Returns a dictionary representation of this object for storage"""
    return {
        'arn': self.arn,
        'name': self.name,
        'policy_doc': self.policy_doc
    }

def as_dictionary(self) -> dict:
    """Returns a dictionary representation of this OrganizationAccount object. Used for serialization to disk. We
    only return the SCP ARN since it is stored in a separate file."""

    return {
        'account_id': self.account_id,
        'scps': [x.arn for x in self.scps],
        'tags': self.tags
    }

def as_dictionary(self) -> dict:
    """Returns a dictionary representation of this OrganizationTree object. Used for serialization to disk. We
    exclude the SCPs and metadata since `save_organization_to_disk` does those in a separate file."""

    return {
        'org_id': self.org_id,
        'management_account_id': self.management_account_id,
        'root_ous': [x.as_dictionary() for x in self.root_ous],
        'edge_list': [x.to_dictionary() for x in self.edge_list],
        'accounts': self.accounts
    }

def _produce_ou(ou_dict: dict) -> OrganizationNode:
    return OrganizationNode(
        ou_dict['ou_id'],
        ou_dict['ou_name'],
        [OrganizationAccount(x['account_id'], [policies[y] for y in x['scps']], x['tags']) for x in ou_dict['accounts']],
        [_produce_ou(x) for x in ou_dict['child_nodes']],
        [policies[x] for x in ou_dict['scps']],
        ou_dict['tags']
    )

def as_dictionary(self) -> dict:
    """Produces a dictionary representing this Report's contents."""
    return {
        'account': self.account,
        'date_and_time': self.date_and_time.isoformat(),
        'findings': [x.as_dictionary() for x in self.findings],
        'source': self.source
    }

def as_dictionary(self) -> dict:
    """Returns a dictionary representation of this Finding."""
    return {
        'title': self.title,
        'severity': self.severity,
        'impact': self.impact,
        'description': self.description,
        'recommendation': self.recommendation
    }

def _print_help():
    """Prints a helppage for using the REPL."""
    print(_repl_help)

def process_arguments(parsed_args: Namespace) -> int:
    """Given a namespace object generated from parsing args, perform the appropriate tasks. Returns an int
    matching expectations set by /usr/include/sysexits.h for command-line utilities."""

    if parsed_args.account is None:
        session = botocore_tools.get_session(parsed_args.profile)
    else:
        session = None
    graph = graph_actions.get_existing_graph(session, parsed_args.account)

    find_risks.gen_findings_and_print(graph, parsed_args.output_type)

    return 0

def get_regions_to_search(session: botocore.session.Session, service_name: str, region_allow_list: Optional[List[str]] = None, region_deny_list: Optional[List[str]] = None) -> List[str]:
    """Using a botocore Session object, the name of a service, and either an allow-list or a deny-list (but not both),
    return a list of regions to be used during the gathering process. This uses the botocore Session object's
    get_available_regions method as the base list.

    If the allow-list is specified, the returned list is the union of the base list and the allow-list. No error is
    thrown if a region is specified in the allow-list but not included in the base list.

    If the deny-list is specified, the returned list is the base list minus the elements of the deny-list. No error is
    thrown if a region is specified inthe deny-list but not included in the base list.

    A ValueError is thrown if the allow-list AND deny-list are both not None.
    """

    if region_allow_list is not None and region_deny_list is not None:
        raise ValueError('This function allows only either the allow-list or the deny-list, but NOT both.')

    base_list = session.get_available_regions(service_name)

    result = []

    if region_allow_list is not None:
        for element in base_list:
            if element in region_allow_list:
                result.append(element)
    elif region_deny_list is not None:
        for element in base_list:
            if element not in region_deny_list:
                result.append(element)
    else:
        result = base_list

    logger.debug('Final list of regions for {}: {}'.format(service_name, result))

    return result

def _map_account_ou_paths(org_tree: OrganizationTree) -> dict:
    """Given an OrganizationTree, create a map from account -> ou path"""
    result = {}

    def _traverse(org_node: OrganizationNode, base_string: str):
        full_node_str = '{}{}/'.format(base_string, org_node.ou_id)
        for account in org_node.accounts:
            result[account] = full_node_str
        for child_node in org_node.child_nodes:
            _traverse(child_node, full_node_str)

    for root_ou in org_tree.root_ous:
        _traverse(root_ou, '{}/'.format(org_tree.org_id))

    return result

def _update_accounts_with_ou_path_map(org_id: str, account_ou_map: dict, root_dir: str):
    """Given a map produced by `_map_account_ou_paths` go through the available on-disk graphs and update metadata
    appropriately."""

    for account, ou_path in account_ou_map.items():
        potential_path = os.path.join(root_dir, account.account_id, 'metadata.json')
        if os.path.exists(os.path.join(potential_path)):
            try:
                fd = open(potential_path, 'r')
                metadata = json.load(fd)
                new_org_data = {
                    'org-id': org_id,
                    'org-path': ou_path
                }
                logger.debug('Updating {} with org data: {}'.format(account.account_id, new_org_data))
                metadata['org-id'] = org_id
                metadata['org-path'] = ou_path
                fd.close()

                fd = open(potential_path, 'w')
                json.dump(metadata, fd, indent=4)
            except IOError as ex:
                logger.debug('IOError when reading/writing metadata of {}: {}'.format(account.account_id, str(ex)))
                continue
        else:
            logger.debug(
                'Account {} of organization {} does not have a Graph. You will need to update the '
                'organization data at a later point (`pmapper orgs update --org $ORG_ID`).'.format(account.account_id, org_id)
            )  # warning gets thrown up by caller, no need to reiterate

def _traverse(org_node: OrganizationNode, base_string: str):
    full_node_str = '{}{}/'.format(base_string, org_node.ou_id)
    for account in org_node.accounts:
        result[account] = full_node_str
    for child_node in org_node.child_nodes:
        _traverse(child_node, full_node_str)

def __init__(self, arn: str, id_value: str, attached_policies: Optional[List[Policy]],
             group_memberships: Optional[List[Group]], trust_policy: Optional[dict],
             instance_profile: Optional[List[str]], num_access_keys: int, active_password: bool, is_admin: bool,
             permissions_boundary: Optional[Union[str, Policy]], has_mfa: bool, tags: Optional[dict]):
    """Constructor. Expects an ARN and ID value. Validates parameters based on the type of Node (User/Role),
    and rejects contradictory arguments like an IAM User with a trust policy.
    """

    resource_value = arns.get_resource(arn)
    if arn is None or not (resource_value.startswith('user/') or resource_value.startswith('role/')):
        raise ValueError('The parameter arn must be a valid ARN for an IAM user or role.')
    self.arn = arn

    if id_value is None or len(id_value) == 0:
        raise ValueError('The parameter id_value must be a non-empty string.')
    self.id_value = id_value

    if attached_policies is None:
        self.attached_policies = []
    else:
        self.attached_policies = attached_policies

    if group_memberships is None:
        self.group_memberships = []
    else:
        self.group_memberships = group_memberships

    if resource_value.startswith('user/') and trust_policy is not None:
        raise ValueError('IAM users do not have trust policies, pass None for the parameter trust_policy.')
    if resource_value.startswith('role/') and (trust_policy is None or not isinstance(trust_policy, dict)):
        raise ValueError('IAM roles have trust policies, which must be passed as a dictionary in trust_policy')
    self.trust_policy = trust_policy  # None denotes no trust policy (not a role), {} denotes empty trust policy

    if resource_value.startswith('user/') and instance_profile is not None:
        raise ValueError('IAM users do not have instance profiles. Pass None for the parameter instance_profile.')
    self.instance_profile = instance_profile

    self.active_password = active_password

    if num_access_keys is None:
        self.access_keys = []
    else:
        self.access_keys = num_access_keys

    self.is_admin = is_admin

    self.permissions_boundary = permissions_boundary  # None denotes no permissions boundary, str denotes need to fill in

    self.has_mfa = has_mfa

    if tags is None:
        self.tags = {}
    else:
        self.tags = tags

    self.cache = {}

def __init__(self, source, destination, reason: str, short_reason: str):
    """Constructor"""
    if source is None:
        raise ValueError('Edges must have a source Node object')
    if destination is None:
        raise ValueError('Edges must have a destination Node object')
    if reason is None:
        raise ValueError('Edges must be constructed with a reason parameter (str)')
    if short_reason is None:
        raise ValueError('Edges must be constructed with a short_reason parameter (str)')

    self.source = source
    self.destination = destination
    self.reason = reason
    self.short_reason = short_reason

def get_edges_between_graphs(graph_a: Graph, graph_b: Graph, scps_a: Optional[List[List[dict]]] = None, scps_b: Optional[List[List[dict]]] = None) -> List[Edge]:
    """Given two Graph objects, return a list of Edge objects that represent the connections between
    the two Graphs (both to and from). Currently only does sts:AssumeRole checks."""

    result = []  # type: List[Edge]

    def _check_assume_role(ga, na, gb, nb, scps) -> bool:
        logger.debug('Checking if {} can access {}'.format(na.arn, nb.arn))

        # load up conditions: inspired by _infer_condition_keys
        conditions = {}
        conditions['aws:CurrentTime'] = dt.datetime.now(dt.timezone.utc).isoformat()
        conditions['aws:EpochTime'] = str(round(dt.datetime.now(dt.timezone.utc).timestamp()))
        conditions['aws:userid'] = na.id_value

        if ':user/' in na.arn:
            conditions['aws:username'] = na.searchable_name().split('/')[1]

        conditions['aws:SecureTransport'] = 'true'
        conditions['aws:PrincipalAccount'] = ga.metadata['account_id']
        conditions['aws:PrincipalArn'] = na.arn
        if 'org-id' in ga.metadata:
            conditions['aws:PrincipalOrgID'] = ga.metadata['org-id']
        if 'org-path' in ga.metadata:
            conditions['aws:PrincipalOrgPaths'] = ga.metadata['org-path']

        for tag_key, tag_value in na.tags.items():
            conditions['aws:PrincipalTag/{}'.format(tag_key)] = tag_value

        # check without MFA
        auth_result = local_check_authorization_full(
            na,
            'sts:AssumeRole',
            nb.arn,
            conditions,
            nb.trust_policy,
            arns.get_account_id(nb.arn),
            scps
        )

        if auth_result:
            return True

        # check with MFA
        conditions.update({
            'aws:MultiFactorAuthAge': '1',
            'aws:MultiFactorAuthPresent': 'true'
        })
        auth_result = local_check_authorization_full(
            na,
            'sts:AssumeRole',
            nb.arn,
            conditions,
            nb.trust_policy,
            arns.get_account_id(nb.arn),
            scps
        )

        return auth_result

    def _describe_edge(na, nb) -> str:
        """Quick method for generating strings describing edges."""
        return '{} -> {}'.format(
            '{}/{}'.format(arns.get_account_id(na.arn), na.searchable_name()),
            '{}/{}'.format(arns.get_account_id(nb.arn), nb.searchable_name())
        )

    for node_a in graph_a.nodes:
        for node_b in graph_b.nodes:
            # check a -> b
            if node_b.searchable_name().startswith('role/'):
                if _check_assume_role(graph_a, node_a, graph_b, node_b, scps_a):
                    logger.info('Found edge: {}'.format(_describe_edge(node_a, node_b)))
                    result.append(Edge(node_a, node_b, 'can call sts:AssumeRole to access', 'STS'))

            # check b -> a
            if node_a.searchable_name().startswith('role/'):
                if _check_assume_role(graph_b, node_b, graph_a, node_a, scps_b):
                    logger.info('Found edge: {}'.format(_describe_edge(node_b, node_a)))
                    result.append(Edge(node_b, node_a, 'can call sts:AssumeRole to access', 'STS'))

    return result

def _describe_edge(na, nb) -> str:
    """Quick method for generating strings describing edges."""
    return '{} -> {}'.format(
        '{}/{}'.format(arns.get_account_id(na.arn), na.searchable_name()),
        '{}/{}'.format(arns.get_account_id(nb.arn), nb.searchable_name())
    )

def get_outbound_edges(self, graph):  # -> List[Edge], can't import Edge/Graph in this module
    """Creates and caches a collection of edges where this (self) Node is the source."""
    if 'outbound_edges' not in self.cache:
        self.cache['outbound_edges'] = []
        if self.is_admin:
            for node in graph.nodes:
                if node == self:
                    continue
                else:
                    self.cache['outbound_edges'].append(
                        principalmapper.common.edges.Edge(
                            self, node, 'can access through administrative actions', 'Admin'
                        )
                    )
        else:
            for edge in graph.edges:
                if edge.source == self:
                    self.cache['outbound_edges'].append(edge)
    return self.cache['outbound_edges']

def describe_edge(self) -> str:
    """Returns a human-readable string explaining the edge"""
    return "{} {} {}".format(
        self.source.searchable_name(),
        self.reason,
        self.destination.searchable_name()
    )

def resource_policy_authorization(node_or_service: Union[Node, str], resource_owner: str, resource_policy: dict,
                                  action_to_check: str, resource_to_check: str,
                                  condition_keys_to_check: Union[dict, CaseInsensitiveDict]) -> ResourcePolicyEvalResult:
    """Returns a ResourcePolicyEvalResult for a given request, based on the resource policy."""

    if isinstance(condition_keys_to_check, dict):
        prepped_condition_keys = CaseInsensitiveDict(condition_keys_to_check)
    else:
        prepped_condition_keys = condition_keys_to_check

    matching_statements = resource_policy_matching_statements(node_or_service, resource_policy, action_to_check,
                                                              resource_to_check, prepped_condition_keys)
    if len(matching_statements) == 0:
        return ResourcePolicyEvalResult.NO_MATCH

    # handle denies outright
    for statement in matching_statements:
        if statement['Effect'] == 'Deny':
            return ResourcePolicyEvalResult.DENY_MATCH

    # handle nodes (IAM Users or Roles)
    if isinstance(node_or_service, Node):
        # if in a different account, check for denies and wrap it up
        if arns.get_account_id(node_or_service.arn) != resource_owner:
            return ResourcePolicyEvalResult.DIFF_ACCOUNT_MATCH

        else:
            node_match = False
            for statement in matching_statements:
                if 'NotPrincipal' in statement:
                    # NotPrincipal means a node match (tested with S3)
                    node_match = True
                elif isinstance(statement['Principal'], str) and statement['Principal'] == '*':
                    # Case: "Principal": "*"
                    node_match = True
                else:
                    # dig through 'AWS' element of Principal for node-matching
                    if 'AWS' in statement['Principal']:
                        for aws_principal in _listify_string(statement['Principal']['AWS']):
                            if node_or_service.arn == aws_principal:
                                node_match = True
            if node_match:
                return ResourcePolicyEvalResult.NODE_MATCH
            else:
                return ResourcePolicyEvalResult.ROOT_MATCH

    else:
        return ResourcePolicyEvalResult.SERVICE_MATCH

def generate_edges_locally(nodes: List[Node], scps: Optional[List[List[dict]]] = None) -> List[Edge]:
    """Generates and returns Edge objects. It is possible to use this method if you are operating offline (infra-as-code).
    """
    result = []

    for node_source in nodes:
        for node_destination in nodes:
            # skip self-access checks
            if node_source == node_destination:
                continue

            # check if source is an admin, if so it can access destination but this is not tracked via an Edge
            if node_source.is_admin:
                continue

            if ':user/' in node_destination.arn:
                # Change the user's access keys
                access_keys_mfa = False

                create_auth_res, mfa_res = query_interface.local_check_authorization_handling_mfa(
                    node_source,
                    'iam:CreateAccessKey',
                    node_destination.arn,
                    {},
                    service_control_policy_groups=scps
                )

                if mfa_res:
                    access_keys_mfa = True

                if node_destination.access_keys == 2:
                    # can have a max of two access keys, need to delete before making a new one
                    auth_res, mfa_res = query_interface.local_check_authorization_handling_mfa(
                        node_source,
                        'iam:DeleteAccessKey',
                        node_destination.arn,
                        {},
                        service_control_policy_groups=scps
                    )
                    if not auth_res:
                        create_auth_res = False  # can't delete target access key, can't generate a new one
                    if mfa_res:
                        access_keys_mfa = True

                if create_auth_res:
                    reason = 'can create access keys to authenticate as'
                    if access_keys_mfa:
                        reason = '(MFA required) ' + reason

                    result.append(
                        Edge(
                            node_source, node_destination, reason, 'IAM'
                        )
                    )

                # Change the user's password
                if node_destination.active_password:
                    pass_auth_res, mfa_res = query_interface.local_check_authorization_handling_mfa(
                        node_source,
                        'iam:UpdateLoginProfile',
                        node_destination.arn,
                        {},
                        service_control_policy_groups=scps
                    )
                else:
                    pass_auth_res, mfa_res = query_interface.local_check_authorization_handling_mfa(
                        node_source,
                        'iam:CreateLoginProfile',
                        node_destination.arn,
                        {},
                        service_control_policy_groups=scps
                    )
                if pass_auth_res:
                    reason = 'can set the password to authenticate as'
                    if mfa_res:
                        reason = '(MFA required) ' + reason
                    result.append(Edge(node_source, node_destination, reason, 'IAM'))

            if ':role/' in node_destination.arn:
                # Change the role's trust doc
                update_role_res, mfa_res = query_interface.local_check_authorization_handling_mfa(
                    node_source,
                    'iam:UpdateAssumeRolePolicy',
                    node_destination.arn,
                    {},
                    service_control_policy_groups=scps
                )
                if update_role_res:
                    reason = 'can update the trust document to access'
                    if mfa_res:
                        reason = '(MFA required) ' + reason
                    result.append(Edge(node_source, node_destination, reason, 'IAM'))

    return result

def generate_edges_locally(nodes: List[Node], scps: Optional[List[List[dict]]] = None) -> List[Edge]:
    """Generates and returns Edge objects. It is possible to use this method if you are operating offline (infra-as-code).
    """

    result = []
    for node_destination in nodes:
        # check if destination is a user, skip if so
        if ':role/' not in node_destination.arn:
            continue

        # check that the destination role can be assumed by EC2
        sim_result = resource_policy_authorization(
            'ec2.amazonaws.com',
            arns.get_account_id(node_destination.arn),
            node_destination.trust_policy,
            'sts:AssumeRole',
            node_destination.arn,
            {},
        )

        if sim_result != ResourcePolicyEvalResult.SERVICE_MATCH:
            continue  # EC2 wasn't auth'd to assume the role

        for node_source in nodes:
            # skip self-access checks
            if node_source == node_destination:
                continue

            # check if source is an admin: if so, it can access destination but this is not tracked via an Edge
            if node_source.is_admin:
                continue

            # check if source can pass the destination role
            mfa_needed = False
            condition_keys = {'iam:PassedToService': 'ec2.amazonaws.com'}
            pass_role_auth, mfa_res = query_interface.local_check_authorization_handling_mfa(
                node_source,
                'iam:PassRole',
                node_destination.arn,
                condition_keys,
                service_control_policy_groups=scps
            )
            if not pass_role_auth:
                continue  # source can't pass the role to use it

            # check if destination has an instance profile, if not: check if source can create it
            if node_destination.instance_profile is None:
                create_ip_auth, mfa_res = query_interface.local_check_authorization_handling_mfa(
                    node_source, 'iam:CreateInstanceProfile', '*', {}, service_control_policy_groups=scps)
                if not create_ip_auth:
                    continue  # node_source can't make the instance profile
                if mfa_res:
                    mfa_needed = True

                create_ip_auth, mfa_res = query_interface.local_check_authorization_handling_mfa(
                    node_source, 'iam:AddRoleToInstanceProfile', node_destination.arn, {}, service_control_policy_groups=scps)
                if not create_ip_auth:
                    continue  # node_source can't attach a new instance profile to node_destination
                if mfa_res:
                    mfa_needed = True

            # check if source can run an instance with the instance profile condition, add edge if so and continue
            if node_destination.instance_profile is not None and len(node_destination.instance_profile) > 0:
                iprofile = node_destination.instance_profile[0]
                condition_keys = {'ec2:InstanceProfile': iprofile}
            else:
                iprofile = '*'
                condition_keys = {}

            create_instance_res, mfa_res = query_interface.local_check_authorization_handling_mfa(
                node_source,
                'ec2:RunInstances',
                '*',
                condition_keys,
                service_control_policy_groups=scps
            )

            if mfa_res:
                mfa_needed = True

            if create_instance_res:
                if iprofile != '*':
                    reason = 'can use EC2 to run an instance with an existing instance profile to access'
                else:
                    reason = 'can use EC2 to run an instance with a newly created instance profile to access'
                if mfa_needed:
                    reason = '(MFA required) ' + reason

                new_edge = Edge(
                    node_source,
                    node_destination,
                    reason,
                    'EC2'
                )
                result.append(new_edge)

            # check if source can run an instance without an instance profile then add the profile, add edge if so
            create_instance_res, mfa_res = query_interface.local_check_authorization_handling_mfa(
                node_source,
                'ec2:RunInstances',
                '*',
                {},
                service_control_policy_groups=scps
            )

            if mfa_res:
                mfa_needed = True

            if create_instance_res:
                attach_ip_res, mfa_res = query_interface.local_check_authorization_handling_mfa(
                    node_source,
                    'ec2:AssociateIamInstanceProfile',
                    '*',
                    condition_keys,
                    service_control_policy_groups=scps
                )

                if iprofile != '*':
                    reason = 'can use EC2 to run an instance and then associate an existing instance profile to ' \
                             'access'
                else:
                    reason = 'can use EC2 to run an instance and then attach a newly created instance profile to ' \
                             'access'

                if mfa_res or mfa_needed:
                    reason = '(MFA required) ' + reason

                if attach_ip_res:
                    new_edge = Edge(
                        node_source,
                        node_destination,
                        reason,
                        'EC2'
                    )
                    result.append(new_edge)

    return result

def return_edges(self, nodes: List[Node], region_allow_list: Optional[List[str]] = None,
                 region_deny_list: Optional[List[str]] = None, scps: Optional[List[List[dict]]] = None,
                 client_args_map: Optional[dict] = None) -> List[Edge]:
    """Fulfills expected method return_edges. If session object is None, runs checks in offline mode."""

    logger.info('Pulling data on Lambda functions')

    if client_args_map is None:
        lambdaargs = {}
    else:
        lambdaargs = client_args_map.get('lambda', {})

    lambda_clients = []
    if self.session is not None:
        lambda_regions = botocore_tools.get_regions_to_search(self.session, 'lambda', region_allow_list, region_deny_list)
        for region in lambda_regions:
            lambda_clients.append(self.session.create_client('lambda', region_name=region, **lambdaargs))

    # grab existing lambda functions
    function_list = []
    for lambda_client in lambda_clients:
        try:
            paginator = lambda_client.get_paginator('list_functions')
