def generate_edges_locally(nodes: List[Node], scps: Optional[List[List[dict]]] = None, launch_configs: Optional[List[dict]] = None) -> List[Edge]:
    """Generates and returns Edge objects related to EC2 AutoScaling.

    It is possible to use this method if you are operating offline (infra-as-code). The `launch_configs` param
    should be a list of dictionary objects with the following expected structure:

    ~~~
    {
        'lc_arn': <Launch Configurations ARN>,
        'lc_iip': <IAM Instance Profile>
    }
    ~~~

    All elements are required, but if there is no instance profile then set the field to None.
    """

    result = []

    # iterate through nodes, setting up the map as well as identifying if the service role is available
    role_lc_map = {}
    service_role_available = False
    for node in nodes:
        # this should catch the normal service role + custom ones with the suffix
        if ':role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling' in node.arn:
            service_role_available = True

        if node.instance_profile is not None:
            for launch_config in launch_configs:
                if launch_config['lc_iip'] in node.instance_profile:
                    if node in role_lc_map:
                        role_lc_map[node].append(launch_config['lc_arn'])
                    else:
                        role_lc_map[node] = [launch_config['lc_arn']]

    for node_destination in nodes:
        # check if destination is a user, skip if so
        if ':role/' not in node_destination.arn:
            continue

        # check that the destination role can be assumed by EC2
        sim_result = resource_policy_authorization(
            'ec2.amazonaws.com',
            arns.get_account_id(node_destination.arn),
            node_destination.trust_policy,
            'sts:AssumeRole',
            node_destination.arn,
            {},
        )

        if sim_result != ResourcePolicyEvalResult.SERVICE_MATCH:
            continue  # EC2 wasn't auth'd to assume the role

        for node_source in nodes:
            # skip self-access checks
            if node_source == node_destination:
                continue

            # check if source is an admin: if so, it can access destination but this is not tracked via an Edge
            if node_source.is_admin:
                continue

            csr_mfa = False  # stash for later ref
            if not service_role_available:
                create_service_role_auth, csr_mfa = query_interface.local_check_authorization_handling_mfa(
                    node_source,
                    'iam:CreateServiceLinkedRole',
                    '*',
                    {
                        'iam:AWSServiceName': 'autoscaling.amazonaws.com'
                    },
                    service_control_policy_groups=scps
                )
                if not create_service_role_auth:
                    continue  # service role can't be used if it doesn't exist or be created

            create_auto_scaling_group_auth, casg_mfa = query_interface.local_check_authorization_handling_mfa(
                node_source,
                'autoscaling:CreateAutoScalingGroup',
                '*',
                {},
                service_control_policy_groups=scps
            )
            if not create_auto_scaling_group_auth:
                continue  # can't create an auto-scaling group -> move along

            if node_destination in role_lc_map:
                if service_role_available:
                    reason = 'can use the EC2 Auto Scaling service role and an existing Launch Configuration to access'
                else:
                    reason = 'can create the EC2 Auto Scaling service role and an existing Launch Configuration to access'

                if csr_mfa or casg_mfa:
                    reason = '(MFA Required) ' + reason

                result.append(Edge(
                    node_source,
                    node_destination,
                    reason,
                    'EC2 Auto Scaling'
                ))

            create_launch_config_auth, clc_mfa = query_interface.local_check_authorization_handling_mfa(
                node_source,
                'autoscaling:CreateLaunchConfiguration',
                '*',
                {},
                service_control_policy_groups=scps
            )

            if not create_launch_config_auth:
                continue  # we're done here

            pass_role_auth, pr_mfa = query_interface.local_check_authorization_handling_mfa(
                node_source,
                'iam:PassRole',
                node_destination.arn,
                {
                    'iam:PassedToService': 'ec2.amazonaws.com'
                },
                service_control_policy_groups=scps
            )

            if pass_role_auth:
                if service_role_available:
                    reason = 'can use the EC2 Auto Scaling service role and create a launch configuration to access'
                else:
                    reason = 'can create the EC2 Auto Scaling service role and create a launch configuration to access'
                if clc_mfa or pr_mfa:
                    reason = '(MFA Required) ' + reason

                result.append(Edge(
                    node_source,
                    node_destination,
                    reason,
                    'EC2 Auto Scaling'
                ))

    return result

def to_dictionary(self) -> dict:
    """Returns a dictionary representation of this object for storage"""
    return {
        'source': self.source.arn,
        'destination': self.destination.arn,
        'reason': self.reason,
        'short_reason': self.short_reason
    }

def search_authorization_for(graph: Graph, principal: Node, action_to_check: str, resource_to_check: str,
                             condition_keys_to_check: _UODict) -> QueryResult:
    """Determines if the passed principal, or any principals it can access, can perform a given action for a
    given resource/condition."""

    if local_check_authorization(principal, action_to_check, resource_to_check, condition_keys_to_check):
        return QueryResult(True, [], principal)

    # Invoke special-case if admin node is not directly authorized to call the given action for the given resource
    if principal.is_admin:
        return QueryResult(True, principal, principal)

    for edge_list in query_utils.get_search_list(graph, principal):
        if local_check_authorization(edge_list[-1].destination, action_to_check, resource_to_check,
                                     condition_keys_to_check):
            return QueryResult(True, edge_list, principal)

    return QueryResult(False, [], principal)

def search_authorization_full(graph: Graph, principal: Node, action_to_check: str, resource_to_check: str,
                              condition_keys_to_check: _UODict, resource_policy: Optional[dict] = None,
                              resource_owner: Optional[str] = None, service_control_policies: List[List[Policy]] = None,
                              session_policy: Optional[dict] = None) -> QueryResult:
    """Determines if the passed principal, or any principals it can access, can perform a given action for a
    given resource/condition. Handles an optional resource policy, an optional SCP list, and an optional
    session policy. SCPs are considered in the full search list, but the session policy is discarded after checking
    if the passed principal has access (we assume it is discarded after each pivot, and that it does NOT affect
    the accessibility of the edges).

    In `local_check_authorization` we usually throw up our hands if the given principal is an admin. But, because of
    how SCPs work (even blocking the root user), we force the full search to give more accurate results. If the
    SCPs param is None, we assume no SCPs are in place and can make the same assumption as in
    `local_check_authorization`.

    If the resource_owner param is not None, and the resource_owner param is None, the `local_check_authorization_full`
    function that gets called will throw a ValueError, so make sure the resource ownership is sorted before calling
    this method."""

    if local_check_authorization_full(principal, action_to_check, resource_to_check, condition_keys_to_check,
                                      resource_policy, resource_owner, service_control_policies, session_policy):
        return QueryResult(True, [], principal)

    if service_control_policies is None and principal.is_admin:
        return QueryResult(True, principal, principal)

    for edge_list in query_utils.get_search_list(graph, principal):
        if local_check_authorization_full(edge_list[-1].destination, action_to_check, resource_to_check, condition_keys_to_check,
                                          resource_policy, resource_owner, service_control_policies, None):
            return QueryResult(True, edge_list, principal)

    return QueryResult(False, [], principal)

def _prepare_condition_context(original_dict: _UODict) -> CaseInsensitiveDict:
    """Returns a CaseInsensitiveDict with the given dictionary contents, while also performing a sanity check
    to ensure that there are no duplicate keys in the provided context."""

    if len(original_dict) != len(set([x.lower() for x in original_dict.keys()])):
        raise ValueError('Detected a duplicate context key/value pair. Ensure that there are no duplicate context '
                         'keys, case-insensitive.')

    return CaseInsensitiveDict(original_dict)

def _infer_condition_keys(principal: Node, current_keys: CaseInsensitiveDict) -> CaseInsensitiveDict:
    """Returns a dictionary with global condition context keys we can infer are set based on the input Node being
    checked. We exclude setting keys that are already set in current_keys.

    Using information from https://docs.aws.amazon.com/IAM/latest/UserGuide/reference_policies_condition-keys.html

    Changes in v1.1.3:
        * Changed param current_keys type to CaseInsensitiveDict
        * Changed return type to CaseInsensitiveDict
    """

    result = CaseInsensitiveDict()

    # Date and Time: aws:CurrentTime and aws:EpochTime
    # TODO: Examine if using datetime.isoformat() is good enough to avoid bugs
    if 'aws:CurrentTime' not in current_keys:
        result['aws:CurrentTime'] = dt.datetime.now(dt.timezone.utc).isoformat()

    if 'aws:EpochTime' not in current_keys:
        result['aws:EpochTime'] = str(round(dt.datetime.now(dt.timezone.utc).timestamp()))

    # UserID and Username: aws:userid and aws:username
    # TODO: Double-check how roles handle aws:username, IIRC it's not filled in
    if 'aws:userid' not in current_keys:
        result['aws:userid'] = principal.id_value

    if ':user/' in principal.arn and 'aws:username' not in current_keys:
        result['aws:username'] = principal.searchable_name().split('/')[1]

    # assumes API requests are made via secure channel (HTTPS)
    if 'aws:SecureTransport' not in current_keys:
        result['aws:SecureTransport'] = 'true'

    if 'aws:PrincipalAccount' not in current_keys:
        result['aws:PrincipalAccount'] = arns.get_account_id(principal.arn)

    if 'aws:PrincipalArn' not in current_keys:
        result['aws:PrincipalArn'] = principal.arn

    # NOTE: tag keys are checked for case-insensitive equality already, no worries about collisions
    for tag_key, tag_value in principal.tags.items():
        if 'aws:PrincipalTag/{}'.format(tag_key) not in current_keys:
            result['aws:PrincipalTag/{}'.format(tag_key)] = tag_value

    return result

def local_check_authorization_full(principal: Node, action_to_check: str, resource_to_check: str,
                                   condition_keys_to_check: _UODict, resource_policy: Optional[dict] = None,
                                   resource_owner: Optional[str] = None,
                                   service_control_policy_groups: Optional[List[List[Policy]]] = None,
                                   session_policy: Optional[dict] = None) -> bool:
    """Determine if a given node is authorized to make an API call. It will perform a full local policy evaluation,
    which includes:

    * Checking for any matching Deny statements in all policies that are given
    * Checking Organization SCPs (if given)
    * Checking the resource policy (if given)
    * Checking the principal's permission boundaries (if the caller has any attached)
    * Checking the session policy (if given)
    * Checking the principal's policies

    This will add condition keys that may be inferred, assuming they are not already set, such as the
    aws:username or aws:userid keys.

    If the resource_policy param is not None but the resource_owner is None, this raises a ValueError, so that must
    be sorted beforehand by any code calling this function."""

    if resource_policy is not None and resource_owner is None:
        raise ValueError('Must specify the AWS Account ID of the owner of the resource when specifying a resource policy')

    conditions_keys_copy = copy.deepcopy(condition_keys_to_check)
    prepped_condition_keys = _prepare_condition_context(conditions_keys_copy)
    prepped_condition_keys.update(_infer_condition_keys(principal, prepped_condition_keys))

    is_not_service_linked_role = not _check_if_service_linked_role(principal)

    logger.debug(
        'Testing authorization for: principal: {}, action: {}, resource: {}, conditions: {}, Resource Policy: {}, SCPs: {}, Session Policy: {}'.format(
            principal.arn,
            action_to_check,
            resource_to_check,
            conditions_keys_copy,
            resource_policy,
            service_control_policy_groups,
            session_policy
        ))

    # Check all policies for a matching deny
    for policy in principal.attached_policies:
        if policy_has_matching_statement(policy, 'Deny', action_to_check, resource_to_check, prepped_condition_keys):
            logger.debug('Explicit Deny: Principal\'s attached policies.')
            return False

    for iam_group in principal.group_memberships:
        for policy in iam_group.attached_policies:
            if policy_has_matching_statement(policy, 'Deny', action_to_check, resource_to_check, prepped_condition_keys):
                logger.debug('Explicit Deny: Principal\'s IAM Group policies')
                return False

    if service_control_policy_groups is not None and is_not_service_linked_role:
        for service_control_policy_group in service_control_policy_groups:
            for service_control_policy in service_control_policy_group:
                if policy_has_matching_statement(service_control_policy, 'Deny', action_to_check, resource_to_check, prepped_condition_keys):
                    logger.debug('Explicit Deny: SCPs')
                    return False

    if resource_policy is not None:
        rp_matching_statements = resource_policy_matching_statements(principal, resource_policy, action_to_check, resource_to_check, prepped_condition_keys)
        for statement in rp_matching_statements:
            if statement['Effect'] == 'Deny':
                logger.debug('Explicit Deny: Resource Policy')
                return False

    if session_policy is not None:
        if policy_has_matching_statement(session_policy, 'Deny', action_to_check, resource_to_check, prepped_condition_keys):
            logger.debug('Explict Deny: Session policy')
            return False

    if principal.permissions_boundary is not None:
        if policy_has_matching_statement(principal.permissions_boundary, 'Deny', action_to_check, resource_to_check, prepped_condition_keys):
            logger.debug('Explicit Deny: Permission Boundary')
            return False

    # Check SCPs
    if service_control_policy_groups is not None and is_not_service_linked_role:
        for service_control_policy_group in service_control_policy_groups:
            # For every group of SCPs (policies attached to the ancestors of the account and the current account), the
            # group of SCPs have to have a matching allow statement
            scp_group_result = False
            for service_control_policy in service_control_policy_group:
                if policy_has_matching_statement(service_control_policy, 'Allow', action_to_check, resource_to_check,
                                                 prepped_condition_keys):
                    scp_group_result = True
                    break

            if not scp_group_result:
                logger.debug('Implicit Deny: SCP group')
                return False

    # Check resource policy
    if resource_policy is not None:
        rp_auth_result = resource_policy_authorization(principal, resource_owner, resource_policy, action_to_check, resource_to_check, prepped_condition_keys)
        if arns.get_account_id(principal.arn) == resource_owner:
            # resource is owned by account
            if arns.get_service(resource_to_check) in ('iam', 'kms'):  # TODO: tuple or list?
                # IAM and KMS require the trust/key policy to match
                if rp_auth_result is not ResourcePolicyEvalResult.NODE_MATCH and rp_auth_result is not ResourcePolicyEvalResult.ROOT_MATCH:
                    logger.debug('IAM/KMS Denial: RP must authorize even with same account')
                    return False
            if rp_auth_result is ResourcePolicyEvalResult.NODE_MATCH:
                # If the specific IAM User/Role is given in the resource policy's Principal element and from the same
                # account as the resource, we're done since we've already done deny-checks and the permission boundaries
                # + session policy + principal policies aren't necessary to grant authorization
                logger.debug('RP approval: skip further evaluation')
                return True
        else:
            # resource is owned by another account
            if rp_auth_result is ResourcePolicyEvalResult.NO_MATCH:
                logger.debug('Cross-Account authorization denied')
                return False

    # Check permission boundary
    if principal.permissions_boundary is not None:
        if not policy_has_matching_statement(principal.permissions_boundary, 'Allow', action_to_check, resource_to_check, prepped_condition_keys):
            logger.debug('Implicit Deny: Permission Boundary')
            return False

    # Check session policy
    if session_policy is not None:
        if not policy_has_matching_statement(session_policy, 'Allow', action_to_check, resource_to_check, prepped_condition_keys):
            logger.debug('Implicit Deny: Session Policy')
            return False

    # Check principal's policies
    for policy in principal.attached_policies:
        if policy_has_matching_statement(policy, 'Allow', action_to_check, resource_to_check, prepped_condition_keys):
            return True  # already did Deny statement checks, so we're done

    # Check principal's IAM Groups policies
    for iam_group in principal.group_memberships:
        for policy in iam_group.attached_policies:
            if policy_has_matching_statement(policy, 'Allow', action_to_check, resource_to_check, prepped_condition_keys):
                return True  # already did Deny statement checks, so we're done

    logger.debug('Implicit Deny: Principal\'s Attached Policies')
    return False

def _check_if_service_linked_role(principal: Node) -> bool:
    """Given a Node, determine if it should be treated as a service-linked role. This affects SCP policy decisions as
    described in
    https://docs.aws.amazon.com/organizations/latest/userguide/orgs_manage_policies_scps.html#not-restricted-by-scp"""

    if ':role/' in principal.arn:
        role_name = principal.arn.split('/')[-1]
        return role_name.startswith('AWSServiceRoleFor')
    return False

def has_matching_statement(principal: Node, effect_value: str, action_to_check: str, resource_to_check: str,
                           condition_keys_to_check: CaseInsensitiveDict) -> bool:
    """Locally determine if a node's attached policies (and group's policies if applicable) has at least one matching
    statement with the given effect. This is the meat of the local policy evaluation.
    """

    for policy in principal.attached_policies:
        if policy_has_matching_statement(policy, effect_value, action_to_check, resource_to_check,
                                         condition_keys_to_check):
            return True

    for group in principal.group_memberships:
        for policy in group.attached_policies:
            if policy_has_matching_statement(policy, effect_value, action_to_check, resource_to_check,
                                             condition_keys_to_check):
                return True

    return False

def policy_has_matching_statement(policy: Union[Policy, dict], effect_value: str, action_to_check: str,
                                  resource_to_check: str,
                                  condition_keys_to_check: CaseInsensitiveDict) -> bool:
    """Searches a specific Policy/dict object for a statement with a matching Effect/Action/Resource/Condition"""

    if isinstance(policy, Policy):
        base_obj = policy.policy_doc
    else:
        base_obj = policy

    # go through each policy_doc
    for statement in _listify_dictionary(base_obj['Statement']):
        if statement['Effect'] != effect_value:
            continue  # skip if effect doesn't match

        matches_action, matches_resource, matches_condition = False, False, False

        # start by checking the action
        if 'Action' in statement:
            for action in _listify_string(statement['Action']):
                if _matches_after_expansion(action_to_check, action):
                    matches_action = True
                    break
        else:  # 'NotAction' in statement
            matches_action = True
            for notaction in _listify_string(statement['NotAction']):
                if _matches_after_expansion(action_to_check, notaction):
                    matches_action = False
                    break  # finish looping
        if not matches_action:
            continue  # cut early

        # if action is good, check resource
        if 'Resource' in statement:
            for resource in _listify_string(statement['Resource']):
                if _matches_after_expansion(resource_to_check, resource, condition_keys_to_check):
                    matches_resource = True
                    break
        elif 'NotResource' in statement:  # 'NotResource' in statement
            matches_resource = True
            for notresource in _listify_string(statement['NotResource']):
                if _matches_after_expansion(resource_to_check, notresource, condition_keys_to_check):
                    matches_resource = False
                    break
        else:
            matches_resource = True  # TODO: examine validity of not using a Resource/NotResource field (trust docs)
        if not matches_resource:
            continue  # cut early

        # if resource is good, check condition
        if 'Condition' in statement:
            matches_condition = _get_condition_match(statement['Condition'], condition_keys_to_check)
        else:
            matches_condition = True

        if matches_action and matches_resource and matches_condition:
            return True

    return False

def _get_condition_match(condition: Dict[str, Dict[str, Union[str, List]]], context: CaseInsensitiveDict) -> bool:
    """
    Internal method. It digs through Null, Bool, DateX, NumericX, StringX conditions and returns false if any of
    them don't match what the context has.

    Also handles ForAnyValue and ForAllValues

    See: https://docs.aws.amazon.com/IAM/latest/UserGuide/reference_policies_elements_condition_operators.html
    """
    for block in condition.keys():
        # String operators
        if 'String' in block:
            # string comparison after expansion
            if block.startswith('ForAllValues:'):
                # fail to match unless all of the provided context values match
                for policy_key in condition[block]:
                    if policy_key in context.keys():
                        for context_value in _listify_string(context[policy_key]):
                            if context_value != '':
                                if not _get_str_match(
                                        block,
                                        policy_key,
                                        condition[block][policy_key],
                                        CaseInsensitiveDict({policy_key: context_value})):
                                    return False
            elif block.startswith('ForAnyValue:'):
                # fail to match unless at least one of the provided context values match
                no_match = True
                for policy_key in condition[block]:
                    if policy_key in context.keys():
                        for context_value in _listify_string(context[policy_key]):
                            if context_value != '':
                                if _get_str_match(block, policy_key, condition[block][policy_key], context):
                                    no_match = False
                if no_match:
                    return False
            else:
                for policy_context_key in condition[block]:
                    if not _get_str_match(block, policy_context_key, condition[block][policy_context_key], context):
                        return False

        if 'Numeric' in block:
            # convert string to int and compare (floats allowed? how to handle?)
            if block.startswith('ForAllValues:'):
                # fail to match unless all of the provided context values match
                for policy_key in condition[block]:
                    if policy_key in context.keys():
                        for context_value in _listify_string(context[policy_key]):
                            if context_value != '':
                                if not _get_num_match(block, policy_key, condition[block][policy_key], context):
                                    return False
            elif block.startswith('ForAnyValue:'):
                # fail to match unless at least one of the provided context values match
                no_match = True
                for policy_key in condition[block]:
                    if policy_key in context.keys():
                        for context_value in _listify_string(context[policy_key]):
                            if context_value != '':
                                if _get_num_match(block, policy_key, condition[block][policy_key], context):
                                    no_match = False
                if no_match:
                    return False
            else:
                for policy_context_key in condition[block]:
                    if not _get_num_match(block, policy_context_key, condition[block][policy_context_key], context):
                        return False

        if 'Date' in block:
            # need the datetime and dateutil module to do this, do everything in UTC where undefined
            if block.startswith('ForAllValues:'):
                # fail to match unless all of the provided context values match
                for policy_key in condition[block]:
                    if policy_key in context.keys():
                        for context_value in _listify_string(context[policy_key]):
                            if context_value != '':
                                if not _get_date_match(block, policy_key, condition[block][policy_key], context):
                                    return False
            elif block.startswith('ForAnyValue:'):
                # fail to match unless at least one of the provided context values match
                no_match = True
                for policy_key in condition[block]:
                    if policy_key in context.keys():
                        for context_value in _listify_string(context[policy_key]):
                            if context_value != '':
                                if _get_date_match(block, policy_key, condition[block][policy_key], context):
                                    no_match = False
                if no_match:
                    return False
            else:
                for policy_context_key in condition[block]:
                    if not _get_date_match(block, policy_context_key, condition[block][policy_context_key], context):
                        return False

        if 'Bool' in block:
            # boolean comparison
            if block.startswith('ForAllValues:'):
                # fail to match unless all of the provided context values match
                for policy_key in condition[block]:
                    if policy_key in context.keys():
                        for context_value in _listify_string(context[policy_key]):
                            if context_value != '':
                                if not _get_bool_match(block, policy_key, condition[block][policy_key], context):
                                    return False
            elif block.startswith('ForAnyValue:'):
                # fail to match unless at least one of the provided context values match
                no_match = True
                for policy_key in condition[block]:
                    if policy_key in context.keys():
                        for context_value in _listify_string(context[policy_key]):
                            if context_value != '':
                                if _get_bool_match(block, policy_key, condition[block][policy_key], context):
                                    no_match = False
                if no_match:
                    return False
            else:
                for policy_context_key in condition[block]:
                    if not _get_bool_match(block, policy_context_key, condition[block][policy_context_key], context):
                        return False
        if 'BinaryEquals' in block:
            # straight string comparison
            if block.startswith('ForAllValues:'):
                # fail to match unless all of the provided context values match
                for policy_key in condition[block]:
                    if policy_key in context.keys():
                        for context_value in _listify_string(context[policy_key]):
                            if context_value != '':
                                if not _get_straight_str_match(block, policy_key, condition[block][policy_key],
                                                               context):
                                    return False
            elif block.startswith('ForAnyValue:'):
                # fail to match unless at least one of the provided context values match
                no_match = True
                for policy_key in condition[block]:
                    if policy_key in context.keys():
                        for context_value in _listify_string(context[policy_key]):
                            if context_value != '':
                                if _get_straight_str_match(block, policy_key, condition[block][policy_key], context):
                                    no_match = False
                if no_match:
                    return False
            else:
                for policy_context_key in condition[block]:
                    if not _get_straight_str_match(block, policy_context_key, condition[block][policy_context_key],
                                                   context):
                        return False

        if 'IpAddress' in block:
            # need ipaddress module, use ipaddress.ip_address in <ipaddress.ip_network obj>
            if block.startswith('ForAllValues:'):
                # fail to match unless all of the provided context values match
                for policy_key in condition[block]:
                    if policy_key in context.keys():
                        for context_value in _listify_string(context[policy_key]):
                            if context_value != '':
                                if not _get_ipaddress_match(block, policy_key, condition[block][policy_key], context):
                                    return False
            elif block.startswith('ForAnyValue:'):
                # fail to match unless at least one of the provided context values match
                no_match = True
                for policy_key in condition[block]:
                    if policy_key in context.keys():
                        for context_value in _listify_string(context[policy_key]):
                            if context_value != '':
                                if _get_ipaddress_match(block, policy_key, condition[block][policy_key], context):
                                    no_match = False
                if no_match:
                    return False
            else:
                for policy_context_key in condition[block]:
                    if not _get_ipaddress_match(block, policy_context_key, condition[block][policy_context_key],
                                                context):
                        return False

        if 'Arn' in block:
            # string comparison after expansion
            if block.startswith('ForAllValues:'):
                # fail to match unless all of the provided context values match
                for policy_key in condition[block]:
                    if policy_key in context.keys():
                        for context_value in _listify_string(context[policy_key]):
                            if context_value != '':
                                if not _get_arn_match(block, policy_key, condition[block][policy_key], context):
                                    return False
            elif block.startswith('ForAnyValue:'):
                # fail to match if none of the provided context values match
                no_match = True
                for policy_key in condition[block]:
                    if policy_key in context.keys():
                        for context_value in _listify_string(context[policy_key]):
                            if context_value != '':
                                if _get_arn_match(block, policy_key, condition[block][policy_key], context):
                                    no_match = False
                if no_match:
                    return False
            else:
                for policy_context_key in condition[block]:
                    if not _get_arn_match(block, policy_context_key, condition[block][policy_context_key], context):
                        return False

        # handle Null, ForAllValues:Null, ForAnyValue:Null
        if 'Null' in block:
            if block.startswith('ForAllValues:'):
                # fail to match unless all of the provided context values match
                for policy_key in condition[block]:
                    if policy_key in context.keys():
                        for context_value in _listify_string(context[policy_key]):
                            if context_value != '':
                                if not _get_null_match(policy_key, condition[block][policy_key], context):
                                    return False
            elif block.startswith('ForAnyValue:'):
                # fail to match unless at least one of the provided context values match
                no_match = True
                for policy_key in condition[block]:
                    if policy_key in context.keys():
                        for context_value in _listify_string(context[policy_key]):
                            if context_value != '':
                                if _get_null_match(policy_key, condition[block][policy_key], context):
                                    no_match = False
                if no_match:
                    return False
            else:
                for policy_context_key in condition[block]:
                    if not _get_null_match(policy_context_key, condition[block][policy_context_key], context):
                        return False

    return True

def _get_str_match(block: str, policy_key: str, policy_value: Union[str, List[str]], context: CaseInsensitiveDict) -> bool:
    """Helper method for dealing with String* conditions, including: StringEquals, StringNotEquals,
    StringEqualsIgnoreCase, StringNotEqualsIgnoreCase, StringLike, StringNotLike

    Observed policy simulator behavior for Unicode: if I compare the following, it returns denied:

    * ê <- 'LATIN SMALL LETTER E WITH CIRCUMFLEX'
    * ê <- 'LATIN SMALL LETTER E' + 'COMBINING CIRCUMFLEX ACCENT'

    So even though they're the "same" they end up not matching.

    Observed policy simulator behavior for capitalization: if I compare the following, it returns denied:

    * ß
    * ss

    So even though they're the "same" after casefolding (str casefold method) they end up not matching.

    Just using lower() on the strings is enough to match the policy simulator behavior without having to dip into the
    insanity of unicode.

    Many thanks to https://stackoverflow.com/a/45745761 for the extra information.
    """

    if_exists_op = 'IfExists' in block

    if 'StringEquals' in block:
        if policy_key not in context:
            return if_exists_op
        for value in _listify_string(policy_value):
            for context_value in _listify_string(context[policy_key]):
                if 'IgnoreCase' in block:
                    if value.lower() == context_value.lower():
                        return True
                else:
                    if value == context_value:
                        return True
        return False
    elif 'StringLike' in block:
        if policy_key not in context:
            return if_exists_op
        for value in _listify_string(policy_value):
            for context_value in _listify_string(context[policy_key]):
                if _expand_str_and_compare(value, context_value):
                    return True
        return False
    elif 'StringNotEquals' in block:
        if policy_key not in context:
            return True
        for value in _listify_string(policy_value):
            for context_value in _listify_string(context[policy_key]):
                if 'IgnoreCase' in block:
                    if value.lower() == context_value.lower():
                        return False
                else:
                    if value == context_value:
                        return False
        return True
    elif 'StringNotLike' in block:
        if policy_key not in context:
            return if_exists_op
        for value in _listify_string(policy_value):
            for context_value in _listify_string(context[policy_key]):
                if _expand_str_and_compare(value, context_value):
                    return False
        return True

def _get_num_match(block: str, policy_key: str, policy_value: Union[str, List[str]], context: CaseInsensitiveDict) -> bool:
    """Helper method for dealing with Numeric* conditions, including: NumericEquals, NumericNotEquals,
    NumericLessThan, NumericLessThanEquals, NumericGreaterThan, NumericGreaterThanEquals

    Parses the string inputs into numbers before doing comparisons.
    """

    if_exists_op = 'IfExists' in block

    if block == 'NumericEquals':
        if policy_key not in context:
            return if_exists_op
        for value in _listify_string(policy_value):
            value_num = ast.literal_eval(value)
            for context_value in _listify_string(context[policy_key]):
                context_value_num = ast.literal_eval(context_value)
                if value_num == context_value_num:
                    return True
        return False
    elif block == 'NumericNotEquals':
        if policy_key not in context:
            return True
        for value in _listify_string(policy_value):
            value_num = ast.literal_eval(value)
            for context_value in _listify_string(context[policy_key]):
                context_value_num = ast.literal_eval(context_value)
                if value_num == context_value_num:
                    return False
        return True
    else:
        if policy_key not in context:
            return if_exists_op
        for value in _listify_string(policy_value):
            value_num = ast.literal_eval(value)
            for context_value in _listify_string(context[policy_key]):
                context_value_num = ast.literal_eval(context_value)
                if block == 'NumericLessThan':
                    if context_value_num < value_num:
                        return True
                elif block == 'NumericLessThanEquals':
                    if context_value_num <= value_num:
                        return True
                elif block == 'NumericGreaterThan':
                    if context_value_num > value_num:
                        return True
                elif block == 'NumericGreaterThanEquals':
                    if context_value_num >= value_num:
                        return True
        return False

def _get_bool_match(block: str, policy_key: str, policy_value: Union[str, List[str]], context: CaseInsensitiveDict) -> bool:
    """Helper method for dealing with Bool. For 'true' policy values, returns True if context has 'true' as a value. For
    'false' policy values, returns True if context has value that's not 'true'. Returns False if no context value.
    """

    if_exists_op = 'IfExists' in block

    if policy_key not in context:
        return if_exists_op

    for value in _listify_string(policy_value):
        for context_value in _listify_string(context[policy_key]):
            if value == 'true' and context_value.lower() == 'true':
                return True
            if value == 'false' and context_value.lower() != 'true':
                return True

    return False

def _get_straight_str_match(block: str, policy_key: str, policy_value: Union[str, List[str]], context: CaseInsensitiveDict) -> bool:
    """Helper method for dealing with BinaryEquals

    Does a straight string comparison to search for a match.
    """

    # can knock this out up here
    if policy_key not in context:
        return False

    for value in _listify_string(policy_value):
        for context_value in _listify_string(context[policy_key]):
            if value == context_value:
                return True

    return False

def _get_ipaddress_match(block: str, policy_key: str, policy_value: Union[str, List[str]], context: CaseInsensitiveDict) -> bool:
    """Helper method for dealing with *IpAddress conditions: IpAddress, NotIpAddress

    Parses the policy value as an IPvXNetwork, then the context value as an IPvXAddress, then uses
    the `in` operator to determine a match.
    """

    if_exists_op = 'IfExists' in block

    for value in _listify_string(policy_value):
        value_net = ipaddress.ip_network(value)
        if block == 'IpAddress':
            if policy_key not in context:
                return if_exists_op
            for context_value in _listify_string(context[policy_key]):
                context_value_addr = ipaddress.ip_address(context_value)
                if context_value_addr in value_net:
                    return True
        else:
            if policy_key not in context:
                return True  # simulator behavior: treat absence as approval
            for context_value in _listify_string(context[policy_key]):
                context_value_addr = ipaddress.ip_address(context_value)
                if context_value_addr in value_net:
                    return False

    # Finished loops without an answer, give defaults
    if block == 'IpAddress':
        return False
    else:
        return True

def _get_date_match(block: str, policy_key: str, policy_value: Union[str, List[str]], context: CaseInsensitiveDict) -> bool:
    """Helper method for dealing with Date* conditions: DateEquals, DateNotEquals, DateGreaterThan,
    DateGreaterThanEquals, DateLessThan, DateLessThanEquals.

    Parses values by distinguishing between epoch values and ISO 8601/RFC 3339 datetimestamps. Assumes
    the timezone is UTC when not specified.
    """

    if_exists_op = 'IfExists' in block

    for value in _listify_string(policy_value):
        value_dt = _convert_timestamp_to_datetime_obj(value)
        if block == 'DateEquals':
            if policy_key not in context:
                return if_exists_op
            for context_value in _listify_string(context[policy_key]):
                context_value_dt = _convert_timestamp_to_datetime_obj(context_value)
                if value_dt == context_value_dt:
                    return True
        elif block == 'DateNotEquals':
            if policy_key not in context:
                return True
            for context_value in _listify_string(context[policy_key]):
                context_value_dt = _convert_timestamp_to_datetime_obj(context_value)
                if value_dt == context_value_dt:
                    return False
        else:  # block == 'DateGreaterThan' or 'DateGreaterThanEquals' or 'DateLessThan' or 'DateLessThanEquals'
            if policy_key not in context:
                return if_exists_op
            for context_value in _listify_string(context[policy_key]):
                context_value_dt = _convert_timestamp_to_datetime_obj(context_value)
                if block == 'DateGreaterThan':
                    if context_value_dt > value_dt:
                        return True
                elif block == 'DateGreaterThanEquals':
                    if context_value_dt >= value_dt:
                        return True
                elif block == 'DateLessThan':
                    if context_value_dt < value_dt:
                        return True
                elif block == 'DateLessThanEquals':
                    if context_value_dt <= value_dt:
                        return True
            return False
    # Finished loops, give default answers
    if block == 'DateEquals':
        return False
    elif block == 'DateNotEquals':
        return True
    else:  # DateGreaterThan, DateGreaterThanEquals, DateLessThan, DateLessThanEquals
        return False

def _get_arn_match(block: str, policy_key: str, policy_value: Union[str, List[str]], context: CaseInsensitiveDict) -> bool:
    """Helper method for dealing with Arn* conditions: ArnEquals, ArnLike, ArnNotEquals, ArnNotLike"""

    if_exists_op = 'IfExists' in block

    for value in _listify_string(policy_value):
        if 'Not' in block:
            if policy_key not in context:
                return True  # policy simulator behavior: returns Allowed when context is null for given key in ArnNot*
            for context_value in _listify_string(context[policy_key]):
                if not arns.validate_arn(context_value):
                    return False  # policy simulator behavior: reject if provided value isn't a legit ARN
                if _matches_after_expansion(context_value, value):
                    return False
        else:
            if policy_key not in context:
                return if_exists_op
            for context_value in _listify_string(context[policy_key]):
                if not arns.validate_arn(context_value):
                    continue  # skip invalid arns
                if _matches_after_expansion(context_value, value):
                    return True

    # Made it through the loops without an answer, give default response
    if 'Not' in block:
        return True
    else:
        return False

def _get_null_match(policy_key: str, policy_value: Union[str, List[str]], context: CaseInsensitiveDict) -> bool:
    """Helper method for dealing with Null conditions"""
    for value in _listify_string(policy_value):
        if value == 'true':  # key is expected not to be in context, or empty
            if policy_key not in context or context[policy_key] == '':
                return True
        else:  # key is expected to be in the context with a non-empty value
            if policy_key in context and context[policy_key] != '':
                return True
    return False

def resource_policy_matching_statements(node_or_service: Union[Node, str], resource_policy: dict,
                                        action_to_check: str, resource_to_check: str,
                                        condition_keys_to_check: CaseInsensitiveDict) -> list:
    """Returns if a resource policy has a matching statement for a given service (ec2.amazonaws.com for example)."""

    results = []

    for statement in _listify_dictionary(resource_policy['Statement']):
        matches_principal, matches_action, matches_resource, matches_condition = False, False, False, False
        if 'Principal' in statement:  # should be a dictionary
            if statement['Principal'] == '*':
                matches_principal = True
            if isinstance(node_or_service, Node):
                if 'AWS' in statement['Principal']:
                    if _principal_matches_in_statement(node_or_service, _listify_string(statement['Principal']['AWS'])):
                        matches_principal = True
            else:
                if 'Service' in statement['Principal']:
                    if node_or_service in _listify_string(statement['Principal']['Service']):
                        matches_principal = True
        else:  # 'NotPrincipal' in statement:
            matches_principal = True
            if isinstance(node_or_service, Node):
                if 'AWS' in statement['NotPrincipal']:
                    if _principal_matches_in_statement(node_or_service, _listify_string(statement['NotPrincipal']['AWS'])):
                        matches_principal = False
            else:
                if 'Service' in statement['NotPrincipal']:
                    if node_or_service in _listify_string(statement['NotPrincipal']['Service']):
                        matches_principal = False

        if not matches_principal:
            continue

        # if principal is good, proceed to check the Action, process depending on prefix
        matches_action = _statement_matches_action(statement, action_to_check, condition_keys_to_check, True)
        if not matches_action:
            continue

        # if action is good, proceed to check resource
        matches_resource = _statement_matches_resource(statement, resource_to_check, condition_keys_to_check)
        if not matches_resource:
            continue

        # if resource is good, check condition
        if 'Condition' in statement:
            matches_condition = _get_condition_match(statement['Condition'], condition_keys_to_check)
        else:
            matches_condition = True

        if matches_principal and matches_action and matches_resource and matches_condition:
            results.append(statement)

    return results

def _principal_matches_in_statement(principal: Node, aws_principal_field: list):
    """Helper function for locally determining a principal matches a resource policy's statement"""
    for value in aws_principal_field:
        if principal.arn == value:
            return True
        elif principal.id_value == value:
            return True
        elif arns.get_account_id(principal.arn) == value:
            return True
        elif value == '*':
            return True
        else:
            principal_root_str = 'arn:{}:iam::{}:root'.format(arns.get_partition(principal.arn),
                                                              arns.get_account_id(principal.arn))
            if principal_root_str == value:
                return True
    return False

def policies_include_matching_allow_action(principal: Node, action_to_check: str) -> bool:
    """Helper function for online-testing. Does a 'light' scan of a principal's policies to determine if any of
    their statements have an Allow statement with a matching action. Helps reduce unecessary API calls to
    iam:SimulatePrincipalPolicy.

    **NOTE:** Not something being used right now, given that all policy evaluation is local
    """

    for policy in principal.attached_policies:
        for statement in _listify_dictionary(policy.policy_doc['Statement']):
            if statement['Effect'] != 'Allow':
                continue
            if 'Action' in statement:
                for action in _listify_string(statement['Action']):
                    if _matches_after_expansion(action_to_check, action):
                        return True
            else:  # 'NotAction' in statement
                return True  # so broad that we'd need to simulate to make sure
    return False

def _statement_matches_action(statement: dict, action: str, condition_keys: Optional[CaseInsensitiveDict] = None,
                              is_resource_policy_check: bool = False) -> bool:
    """Helper function, returns True if the given action is in the given policy statement"""
    exempted_services = ('sns', 'sqs')
    if 'Action' in statement:
        for item in _listify_string(statement['Action']):
            if not is_resource_policy_check:
                if _matches_after_expansion(action, item, condition_keys):
                    return True
            else:
                if action.startswith('SNS') or action.startswith('SQS') or item.startswith('SNS') or item.startswith(
                        'SQS'):
                    action_parts = action.split(':')
                    item_parts = action.split(':')
                    new_action = '{}:{}'.format(action_parts[0].lower(), action_parts[1])
                    new_item = '{}:{}'.format(item_parts[0].lower(), item_parts[1])
                    if _matches_after_expansion(new_action, new_item, condition_keys):
                        return True
                else:
                    if _matches_after_expansion(action, item, condition_keys):
                        return True
        return False
    elif 'NotAction' in statement:
        result = True
        for item in _listify_string(statement['NotAction']):
            if not is_resource_policy_check:
                if _matches_after_expansion(action, item, condition_keys):
                    result = False
                    break
            else:
                if action.startswith('SNS') or action.startswith('SQS') or item.startswith('SNS') or item.startswith(
                        'SQS'):
                    action_parts = action.split(':')
                    item_parts = action.split(':')
                    new_action = '{}:{}'.format(action_parts[0].lower(), action_parts[1])
                    new_item = '{}:{}'.format(item_parts[0].lower(), item_parts[1])
                    if _matches_after_expansion(new_action, new_item, condition_keys):
                        result = False
                        break
                else:
                    if _matches_after_expansion(action, item, condition_keys):
                        result = False
                        break
        return result
    else:
        return True

def _statement_matches_resource(statement: dict, resource: str, condition_keys: Optional[CaseInsensitiveDict] = None) -> bool:
    """Helper function, returns True if the given resource is in the given policy statement"""
    if 'Resource' in statement:
        for item in _listify_string(statement['Resource']):
            if _matches_after_expansion(resource, item, condition_keys):
                return True
        return False
    elif 'NotResource' in statement:
        result = True
        for item in _listify_string(statement['NotResource']):
            if _matches_after_expansion(resource, item, condition_keys):
                result = False
                break
        return result
    else:
        return True

def _listify_dictionary(target_object: Union[List[Dict], Dict]) -> List[Dict]:
    """Helper function that takes a dictionary and returns it wrapped in a list"""
    if isinstance(target_object, list):
        return target_object
    else:
        return [target_object]

def _listify_string(target_object: Union[List[str], str]) -> List[str]:
    """Helper function that takes a string and returns it wrapped in a list"""
    if isinstance(target_object, list):
        return target_object
    else:
        return [target_object]

def _convert_timestamp_to_datetime_obj(timestamp: str):
    """Helper method for the helper method: converts string to datetime object"""
    if '-' in timestamp:  # policy simulator behavior: datetimestamps need dashes, even though ISO 8601 doesn't (?)
        # parse as ISO 8601/RFC 3339
        result = dup.parse(timestamp)
        if result.tzinfo is None:
            result.replace(tzinfo=dt.timezone.utc)
        return result
    else:
        # parse as epoch timestamp
        return dt.datetime.fromtimestamp(float(timestamp), dt.timezone.utc)  # TODO: concern around float imprecision

def _gen_resource_tag_conditions(tag_list: List[dict]):
    condition_result = {
        # 'aws:TagKeys': []
    }
    for tag in tag_list:
        condition_result.update({
            'aws:ResourceTag/{}'.format(tag['key']): tag['value']
        })
        # TODO: make sure we're handling RequestTag and TagKeys correctly
        # condition_result.update({
        #     'aws:RequestTag/{}'.format(tag['Key']): tag['Value']
        # })
        # condition_result['aws:TagKeys'].append(tag['Key'])
    return condition_result

def get_partition(arn: str):
    """Returns the partition from a string ARN."""
    return arn.split(':')[1]

def get_service(arn: str):
    """Returns the service from a string ARN."""
    return arn.split(':')[2]

def get_region(arn: str):
    """Returns the region from a string ARN."""
    return arn.split(':')[3]

def get_account_id(arn: str):
    """Returns the account ID from a string ARN."""
    return arn.split(':')[4]

def get_resource(arn: str):
    """Returns the resource (trailing part) from a string ARN. Note that we're splitting on colons, so we have to
    join with colons in case the trailing part uses colon-separators instead of forward-slashes.
    """
    return ':'.join(arn.split(':')[5:])

def validate_arn(arn: str) -> bool:
    """Returns true if the provided ARN appears to follow the expected structure of an ARN."""
    arn_arr = arn.split(':')
    if len(arn_arr) < 6:
        return False
    if arn_arr[0] != 'arn':
        return False
    return True

def write_standard_graphml(graph: Graph, filepath: str, with_services: Optional[bool] = False) -> None:
    """The function to generate the standard visualization with a GraphML file: this is all the nodes with the
    admins/privesc highlights in blue/red respectively."""

    node_color_mapping = {}
    for node in graph.nodes:
        if node.is_admin:
            node_color_mapping[node] = 'blue'
        elif can_privesc(graph, node)[0]:
            node_color_mapping[node] = 'red'
        else:
            node_color_mapping[node] = 'white'

    if with_services:
        sam = compose_service_access_map(graph)
    else:
        sam = None


    result = ET.ElementTree(ET.Element(None))
    generate_graphml(node_color_mapping, graph.edges, result, sam)
    result.write(filepath, 'utf-8', True)

def write_privesc_graphml(graph: Graph, filepath: str) -> None:
