def print_result(self, action_param: str, resource_param: str):
    """Prints information about the QueryResult object to stdout."""
    if self.allowed:
        if isinstance(self.edge_list, Node):
            if self.edge_list == self.node:
                # node is an Admin but can't directly call the action
                print('{} CAN BECOME authorized to call action {} for resource {} THRU its admin privileges'.format(
                    self.node.searchable_name(), action_param, resource_param
                ))
            else:
                raise ValueError('Improperly-generated QueryResult object: edge_list is a Node but not the input Node')

        elif len(self.edge_list) == 0:
            # node itself is auth'd
            print('{} IS authorized to call action {} for resource {}'.format(
                self.node.searchable_name(), action_param, resource_param
            ))
        else:
            # node is auth'd through other nodes
            print('{} CAN call action {} for resource {} THRU {}'.format(
                self.node.searchable_name(), action_param, resource_param,
                self.edge_list[-1].destination.searchable_name()
            ))

            # print the path the node has to take
            for edge in self.edge_list:
                print('   {}'.format(edge.describe_edge()))

            # print that the end-edge is authorized to make the call
            print('   {} IS authorized to call action {} for resource {}'.format(
                self.edge_list[-1].destination.searchable_name(),
                action_param,
                resource_param
            ))
    else:
        print('{} CANNOT call action {} for resource {}'.format(
            self.node.searchable_name(), action_param, resource_param
        ))

def write_result(self, action_param: str, resource_param: str, output: io.StringIO):
    """Writes information about the QueryResult object to the given IO interface.

    **Change, v1.1.x:** The `output` param is no longer optional.
    """

    if self.allowed:
        if isinstance(self.edge_list, Node) and self.edge_list == self.node:
            # node is an Admin but can't directly call the action
            output.write('{} IS authorized to call action {} for resource {} THRU its admin privileges\n'.format(
                self.node.searchable_name(), action_param, resource_param
            ))
        if len(self.edge_list) == 0:
            # node itself is auth'd
            output.write('{} IS authorized to call action {} for resource {}\n'.format(
                self.node.searchable_name(), action_param, resource_param))

        else:
            # node is auth'd through other nodes
            output.write('{} CAN call action {} for resource {} THRU {}\n'.format(
                self.node.searchable_name(), action_param, resource_param,
                self.edge_list[-1].destination.searchable_name()
            ))

            # print the path the node has to take
            for edge in self.edge_list:
                output.write('   {}\n'.format(edge.describe_edge()))

            # print that the end-edge is authorized to make the call
            output.write('   {} IS authorized to call action {} for resource {}\n'.format(
                self.edge_list[-1].destination.searchable_name(),
                action_param,
                resource_param
            ))
    else:
        output.write('{} CANNOT call action {} for resource {}\n'.format(
            self.node.searchable_name(), action_param, resource_param
        ))

def as_json(self):
    """Produces a JSON representation of this query's result."""
    if isinstance(self.edge_list, Node):
        edge_rep = [{
            'src': self.edge_list.arn,
            'dst': self.edge_list.arn
        }]
    else:
        edge_rep = []
        for edge in self.edge_list:
            edge_rep.append({
                'src': edge.source.arn,
                'dst': edge.destination.arn
            })
    return json.dumps({
        'allowed': self.allowed,
        'node': self.node.arn,
        'edge_list': edge_rep
    })

def handle_preset(graph: Graph, query: str, skip_admins: bool = False) -> None:
    """Interprets, executes, and outputs the result to a preset query."""
    tokens = re.split(r'\s+', query, flags=re.UNICODE)
    if tokens[1] == 'privesc':
        if len(tokens) < 3:
            _print_query_help()
            return
        privesc.handle_preset_query(graph, tokens, skip_admins)
    elif tokens[1] == 'connected':
        if len(tokens) < 4:
            _print_query_help()
            return
        connected.handle_preset_query(graph, tokens, skip_admins)
    elif tokens[1] == 'clusters':
        if len(tokens) < 3:
            _print_query_help()
            return
        clusters.handle_preset_query(graph, tokens, skip_admins)
    elif tokens[1] == 'endgame':
        if len(tokens) < 3:
            _print_query_help()
            return
        endgame.handle_preset_query(graph, tokens, skip_admins)
    elif tokens[1] == 'serviceaccess':
        serviceaccess.handle_preset_query(graph, tokens, skip_admins)
    elif tokens[1] == 'wrongadmin':
        wrongadmin.handle_preset_query(graph, tokens, skip_admins)
    else:
        _print_query_help()
        return

def _write_query_help(output: io.StringIO) -> None:
    """Writes information about querying"""
    output.write(_query_help_string)

def _print_query_help() -> None:
    """Prints information about querying"""
    print(_query_help_string.strip())

def argquery(graph: Graph, principal_param: Optional[str], action_param: Optional[str], resource_param: Optional[str],
             condition_param: Optional[dict], preset_param: Optional[str], skip_admins: bool = False,
             resource_policy: dict = None, resource_owner: str = None, include_unauthorized: bool = False,
             session_policy: Optional[dict] = None, scps: Optional[List[List[dict]]] = None) -> None:
    """Splits between running a normal argquery and the presets."""
    if preset_param is not None:
        if preset_param == 'privesc':
            # Validate params
            if action_param is not None:
                raise ValueError('For the privesc preset query, the --action parameter should not be set.')
            if resource_param is not None and resource_param != '*':
                raise ValueError('For the privesc preset query, the --resource parameter should not be set or set to \'*\'.')

            nodes = []
            if principal_param is None or principal_param == '*':
                nodes.extend(graph.nodes)
            else:
                nodes.append(graph.get_node_by_searchable_name(principal_param))

            privesc.print_privesc_results(graph, nodes, skip_admins)
        elif preset_param == 'connected':
            # Validate params
            if action_param is not None:
                raise ValueError('For the privesc preset query, the --action parameter should not be set.')

            source_nodes = []
            dest_nodes = []
            if principal_param is None or principal_param == '*':
                source_nodes.extend(graph.nodes)
            else:
                source_nodes.append(graph.get_node_by_searchable_name(principal_param))

            if resource_param is None or resource_param == '*':
                dest_nodes.extend(graph.nodes)
            else:
                dest_nodes.append(graph.get_node_by_searchable_name(resource_param))

            connected.write_connected_results(graph, source_nodes, dest_nodes, skip_admins)
        elif preset_param == 'clusters':
            # validate params
            if action_param is not None:
                raise ValueError('For the clusters preset query, the --action parameter should not be set.')

            if resource_param is None:
                raise ValueError('For the clusters preset query, the --resource parameter must be set.')

            clusters.handle_preset_query(graph, ['', '', resource_param], skip_admins)
        elif preset_param == 'endgame':
            # validate params
            if action_param is not None:
                raise ValueError('For the clusters preset query, the --action parameter should not be set.')

            if resource_param is None:
                raise ValueError('For the endgame preset query, the --resource parameter must be set.')

            endgame.handle_preset_query(graph, ['', '', resource_param], skip_admins)
        elif preset_param == 'serviceaccess':
            serviceaccess.handle_preset_query(graph, [], skip_admins)
        elif preset_param == 'wrongadmin':
            wrongadmin.handle_preset_query(graph, [], skip_admins)
        else:
            raise ValueError('Parameter for "preset" is not valid. Expected values: "privesc", "connected", '
                             '"clusters", "endgame", "serviceaccess", or "wrongadmin".')

    else:
        argquery_response(graph, principal_param, action_param, resource_param, condition_param, skip_admins,
                          resource_policy, resource_owner, include_unauthorized, session_policy, scps)

def argquery_response(graph: Graph, principal_param: Optional[str], action_param: str, resource_param: Optional[str],
                      condition_param: Optional[dict], skip_admins: bool = False, resource_policy: dict = None,
                      resource_owner: str = None, include_unauthorized: bool = False,
                      session_policy: Optional[dict] = None, scps: Optional[List[List[dict]]] = None) -> None:
    """Prints the output of a non-preset argquery"""
    result = []

    if resource_param is None:
        resource_param = '*'

    if condition_param is None:
        condition_param = {}

    # Collect together nodes
    if principal_param is None or principal_param == '*':
        if skip_admins:
            nodes = [x for x in graph.nodes if not x.is_admin]
        else:
            nodes = graph.nodes
    else:
        target_node = graph.get_node_by_searchable_name(principal_param)
        if skip_admins and target_node.is_admin:
            return
        else:
            nodes = [target_node]

    # go through all nodes
    for node in nodes:
        result.append(
            search_authorization_full(
                graph,
                node,
                action_param,
                resource_param,
                condition_param,
                resource_policy,
                resource_owner,
                scps,
                session_policy
            )
        )

    for query_result in result:
        if query_result.allowed or include_unauthorized:
            query_result.print_result(action_param, resource_param)
            print()

def is_connected(graph: Graph, source: Node, destination: Node) -> bool:
    """helper function to express if source and node are connected"""
    if source.is_admin:
        return True

    for node_list in get_search_list(graph, source):
        if node_list[-1].destination == destination:
            return True

    return False

def pull_cached_resource_policy_by_arn(graph: Graph, arn: Optional[str], query: str = None) -> Union[Policy, dict]:
    """Function that pulls a resource policy that's cached on-disk from the given Graph object.

    Returns either a Policy object or a dictionary representing the resource policy. Caller is responsible
    for checking before sending it along to other components.

    Raises ValueError if it is not able to be retrieved.
    """
    if query is not None:
        if arn is not None:
            raise ValueError('Must specify either arn or query, not both.')
        pattern = re.compile(r'.*(arn:[^:]*:[^:]*:[^:]*:[^:]*:\S+).*')
        matches = pattern.match(query)
        if matches is None:
            raise ValueError('Resource policy retrieval error: could not extract resource ARN from query')
        arn = matches.group(1)
    if '?' in arn or '*' in arn:
        raise ValueError('Resource component from query must not have wildcard (? or *) when evaluating '
                         'resource policies.')

    logger.debug('Looking for cached policy for {}'.format(arn))

    # manipulate the ARN as needed
    service = arns.get_service(arn)
    if service == 's3':
        # we only need the ARN of the bucket
        search_arn = 'arn:{}:s3:::{}'.format(arns.get_partition(arn), arns.get_resource(arn).split('/')[0])
    elif service == 'iam':
        # special case: trust policies
        role_name = arns.get_resource(arn).split('/')[-1]  # get the last part of :role/path/to/role_name
        role_node = graph.get_node_by_searchable_name('role/{}'.format(role_name))
        return role_node.trust_policy
    elif service == 'sns':
        search_arn = arn
    elif service == 'sqs':
        search_arn = arn
    elif service == 'kms':
        search_arn = arn
    elif service == 'secretsmanager':
        search_arn = arn
    else:
        raise NotImplementedError('Service policies for {} are not (currently) cached.'.format(service))

    for policy in graph.policies:
        if search_arn == policy.arn:
            return policy

    raise ValueError('Unable to locate a cached policy for resource {}'.format(arn))

def get_edges_interaccount(source_graph: Graph, inter_account_edges: List[Edge], node: Node, ignored_nodes: List[Node]) -> List[Edge]:
    """Given a Node, the Graph it belongs to, a list of inter-account Edges, and a list of Nodes to skip, this returns
    any Edges where the Node is the source element as long as the destination element isn't included in the skipped Nodes.

    If the given node is an admin, those Edge objects get generated and returned.
    """

    result = []

    for outbound_edge in node.get_outbound_edges(source_graph):
        if outbound_edge.destination not in ignored_nodes:
            result.append(outbound_edge)

    for inter_account_edge in inter_account_edges:
        if inter_account_edge.source == node and inter_account_edge.destination not in ignored_nodes:
            result.append(inter_account_edge)

    return result

def _grab_policies_and_traverse(org_nodes: List[OrganizationNode], parts, index, account_id, result):
    for org_node in org_nodes:
        if org_node.ou_id != parts[index]:
            continue
        else:
            # ASSUMPTION: all OUs/Accounts in an org HAVE to have at least one policy when SCPs are enabled, so this
            # catches the alternative and does an early return of None. None is interpreted by querying mechanisms
            # as meaning SCPs are NOT considered during authorization
            if len(org_node.scps) == 0:
                return None
            result.append([x.policy_doc for x in org_node.scps])
            if parts[index + 1] == '':
                for account in org_node.accounts:
                    if account.account_id == account_id:
                        result.append([x.policy_doc for x in account.scps])
            else:
                _grab_policies_and_traverse(org_node.child_nodes, parts, index + 1, account_id, result)

def _find_path_or_traverse(search_path: List[str], org_nodes: List[OrganizationNode], target_account: str):
    logger.debug(search_path)
    for org_node in org_nodes:
        search_path.append(org_node.ou_id)
        if target_account in [x.account_id for x in org_node.accounts]:
            return '/'.join(search_path) + '/'
        else:
            traverse_result = _find_path_or_traverse(search_path, org_node.child_nodes, target_account)
            if traverse_result is not None:
                return traverse_result
        search_path.pop()
    return None

def compose_service_access_map(graph: Graph) -> Dict[str, List[Node]]:
    """Given a Graph, create a mapping from services to the IAM Roles in the Graph they can assume."""
    result = {}

    # iterate through all nodes
    for n in graph.nodes:  # type: Node
        # filter to IAM Roles
        if ':role/' not in n.arn:
            continue

        allow_list = []
        deny_list = []
        if 'Statement' not in n.trust_policy:
            continue

        for stmt in n.trust_policy['Statement']:
            if 'Principal' not in stmt:
                continue  # TODO: re-examine inclusion of NotPrincipal in trust docs
            if 'Service' in stmt['Principal']:
                for element in _listify_string(stmt['Principal']['Service']):
                    if stmt['Effect'] == 'Allow':
                        allow_list.append(element)
                    else:
                        deny_list.append(element)

        for allowed in allow_list:
            if allowed in deny_list:
                continue

            if allowed not in result:
                result[allowed] = [n]
            else:
                result[allowed].append(n)

    return result

def compose_endgame_map(graph: Graph, service_to_include: str = '*', skip_admins: bool = False) -> Dict[Policy, List[Node]]:
    """Given a Graph and a service to look at, compose and return a map that includes the different
    users/roles versus the resources they're able to open up for world-access."""

    result = {}

    for policy in graph.policies:
        for service, definition in _service_resource_exposure_map.items():
            if service_to_include == '*' or ':{}:'.format(service_to_include) in policy.arn:
                if definition['pattern'].match(policy.arn) is not None:
                    result[policy] = []

                    for node in graph.nodes:
                        node_confirmed = False

                        if 'conditions' not in node.cache:
                            node.cache['conditions'] = query_interface._infer_condition_keys(node, CaseInsensitiveDict())

                        if (not skip_admins) or (not node.is_admin):
                            for action in definition['actions']:
                                if node_confirmed:
                                    continue

                                query_result = query_interface.local_check_authorization_full(
                                    node, action, policy.arn, node.cache['conditions'], policy.policy_doc, graph.metadata['account_id'],
                                    None, None
                                )

                                if query_result:
                                    node_confirmed = True

                                elif node.has_mfa:
                                    conditions_copy = copy.deepcopy(node.cache['conditions'])
                                    conditions_copy.update({
                                        'aws:MultiFactorAuthAge': '1',
                                        'aws:MultiFactorAuthPresent': 'true'
                                    })
                                    query_result = query_interface.local_check_authorization_full(
                                        node, action, policy.arn, conditions_copy, policy.policy_doc,
                                        graph.metadata['account_id'],
                                        None, None
                                    )
                                    if query_result:
                                        node_confirmed = True

                        if node_confirmed:
                            result[policy].append(node)

    return result

def _is_admin_or_equiv_policy(policy: Policy) -> bool:
    """Given a Policy return true if the policy is the AdministratorAccess policy or if the policy document
    is effectively the same."""

    if ':aws:policy/AdministratorAccess' in policy.arn:
        return True

    for stmt in policy.policy_doc['Statement']:
        action_flag, resource_flag = False, False
        if 'Action' in stmt and 'Resource' in stmt and stmt['Effect'] == 'Allow':
            if isinstance(stmt['Action'], str):
                if stmt['Action'] == '*':
                    action_flag = True
            else:
                for action in stmt['Action']:
                    if action == '*':
                        action_flag = True
                        break

            if isinstance(stmt['Resource'], str):
                if stmt['Resource'] == '*':
                    resource_flag = True
            else:
                for resource in stmt['Resource']:
                    if resource == '*':
                        resource_flag = True
                        break
        if action_flag and resource_flag:
            return True

    return False

def _get_admin_reason(node: Node) -> List[str]:
    """Return a list of reasons why this given node is an admin."""

    result = []
    logger.debug("Checking if {} is an admin".format(node.searchable_name()))
    node_type = arns.get_resource(node.arn).split('/')[0]

    # check if node can modify its own inline policies
    if node_type == 'user':
        action = 'iam:PutUserPolicy'
    else:  # node_type == 'role'
        action = 'iam:PutRolePolicy'
    if query_interface.local_check_authorization_handling_mfa(node, action, node.arn, {})[0]:
        result.append('Can call {} to add/update their own inline policies'.format(action))

    # check if node can attach the AdministratorAccess policy to itself
    if node_type == 'user':
        action = 'iam:AttachUserPolicy'
    else:
        action = 'iam:AttachRolePolicy'
    condition_keys = {'iam:PolicyARN': 'arn:aws:iam::aws:policy/AdministratorAccess'}
    if query_interface.local_check_authorization_handling_mfa(node, action, node.arn, condition_keys)[0]:
        result.append('Can call {} to attach the AdministratorAccess policy to itself'.format(action))

    # check if node can create a role and attach the AdministratorAccess policy or an inline policy
    if query_interface.local_check_authorization_handling_mfa(node, 'iam:CreateRole', '*', {})[0]:
        if query_interface.local_check_authorization_handling_mfa(node, 'iam:AttachRolePolicy', '*',
                                                                  condition_keys)[0]:
            result.append('Can create an IAM Role (iam:CreateRole) and attach the AdministratorAccess policy to it (iam:AttachRolePolicy)'.format(action))
        if query_interface.local_check_authorization_handling_mfa(node, 'iam:PutRolePolicy', '*', condition_keys)[0]:
            result.append('Can create an IAM Role (iam:CreateRole) and create an inline policy for it (iam:PutRolePolicy)'.format(action))

    # check if node can update an attached customer-managed policy (assumes SetAsDefault is set to True)
    for attached_policy in node.attached_policies:
        if attached_policy.arn != node.arn and ':aws:policy/' not in attached_policy.arn:
            if query_interface.local_check_authorization_handling_mfa(node, 'iam:CreatePolicyVersion',
                                                                      attached_policy.arn, {})[0]:
                result.append('Can modify the attached managed policy {} (iam:CreatePolicyVersion)'.format(attached_policy.arn))
                break  # reduce output

    # check if node is a user, and if it can attach or modify any of its groups's policies
    if node_type == 'user':
        for group in node.group_memberships:
            group_name = group.arn.split('/')[-1]

            if query_interface.local_check_authorization_handling_mfa(node, 'iam:PutGroupPolicy', group.arn, {})[0]:
                result.append('Can add/update an inline policy for the group {} (iam:PutGroupPolicy)'.format(group_name))

            if query_interface.local_check_authorization_handling_mfa(node, 'iam:AttachGroupPolicy', group.arn,
                                                                      condition_keys)[0]:
                result.append('Can attach the AdministratorAccess policy to the group {} (iam:AttachGroupPolicy)'.format(group_name))

            for attached_policy in group.attached_policies:
                if attached_policy.arn != group.arn and ':aws:policy/' not in attached_policy.arn:
                    if query_interface.local_check_authorization_handling_mfa(node, 'iam:CreatePolicyVersion',
                                                                              attached_policy.arn, {})[0]:
                        result.append('Can update the managed policy {} that is attached to the group {} (iam:CreatePolicyVersion)'.format(attached_policy.arn, group_name))
                        break  # reduce output

    return result

def compose_wrong_admin_list(graph: Graph) -> List[Tuple[Node, List[str]]]:
    """Given a Graph, return the collection of principals that are admins but do not have the
    AdminstratorAccess policy or an equivalent inline policy, along with a list of what policy/policies
    and statements that could be the source of the admin-access."""

    result = []

    # iterate through all nodes
    for node in graph.nodes:

        # skip non-admins
        if not node.is_admin:
            continue

        # skip principals with Admin or equiv policy
        flag = False
        for attached_policy in node.attached_policies:
            if _is_admin_or_equiv_policy(attached_policy):
                flag = True
                break
        if flag:
            continue

        # skip IAM Users in IAM Groups with Admin or equiv policy
        if ':user/' in node.arn:
            flag = False
            for group in node.group_memberships:
                for attached_policy in group.attached_policies:
                    if _is_admin_or_equiv_policy(attached_policy):
                        flag = True
                        break
                if flag:
                    break
            if flag:
                continue

        # at this point we have a node that's an admin, so let's find the potentially responsible statements
        result.append((node, _get_admin_reason(node)))

    return result

def __init__(self, data=None, **kwargs):
    self._store = OrderedDict()
    if data is None:
        data = {}
    self.update(data, **kwargs)

def lower_items(self):
    """Like iteritems(), but with all lowercase keys."""
    return (
        (lowerkey, keyval[1])
        for (lowerkey, keyval)
        in self._store.items()
    )

def __eq__(self, other):
    if isinstance(other, Mapping):
        other = CaseInsensitiveDict(other)
    else:
        return NotImplemented
    # Compare insensitively
    return dict(self.lower_items()) == dict(other.lower_items())

def handle_preset_query(graph: Graph, tokens: List[str], skip_admins: bool = False) -> None:
    """Handles a human-readable query that's been chunked into tokens, and prints the result."""

    tag_name_target = tokens[2]
    clusters = generate_clusters(graph, tag_name_target)

    print('# Clusters identified on key {}'.format(tag_name_target))
    for k in clusters.keys():
        if k is None:
            continue
        print('{}:'.format(k))
        for n in clusters[k]:
            print('   {}'.format(n.searchable_name()))

    print()
    print('# Boundaries crossed on key {}'.format(tag_name_target))
    for source in clusters.keys():
        if source is None:
            continue

        for destination in clusters.keys():
            if destination is None or source == destination:
                continue

            for src_node in clusters[source]:
                for dst_node in clusters[destination]:
                    connected, path = is_connected(graph, src_node, dst_node)
                    if connected:
                        print('{} can cross boundaries and access {}'.format(
                            src_node.searchable_name(), dst_node.searchable_name()
                        ))
                        for edge in path:
                            print('   {}'.format(edge.describe_edge()))

def generate_clusters(graph: Graph, tag_name_target: str) -> Dict[str, List[Node]]:
    """Given a graph, and a key of a tag to work from, group up all the nodes using those tags."""

    result = {}
    for node in graph.nodes:
        if tag_name_target in node.tags:
            value = node.tags[tag_name_target]
        else:
            value = None

        if value not in result:
            result[value] = [node]
        else:
            result[value].append(node)

    return result

def handle_preset_query(graph: Graph, tokens: List[str], skip_admins: bool = False) -> None:
    """Handles a human-readable query that's been chunked into tokens, and writes the result to output."""
    source_target = tokens[2]
    dest_target = tokens[3]

    source_nodes = []
    dest_nodes = []
    if source_target == '*':
        source_nodes.extend(graph.nodes)
    else:
        source_nodes.append(graph.get_node_by_searchable_name(source_target))

    if dest_target == '*':
        dest_nodes.extend(graph.nodes)
    else:
        dest_nodes.append(graph.get_node_by_searchable_name(dest_target))

    print_connected_results(graph, source_nodes, dest_nodes, skip_admins)

def print_connected_results(graph: Graph, source_nodes: List[Node], dest_nodes: List[Node], skip_admins: bool = False) -> None:
    """Handles a `connected` query and writes the results to output"""
    for snode in source_nodes:
        if skip_admins and snode.is_admin:
            continue

        for dnode in dest_nodes:
            connection_result, path = is_connected(graph, snode, dnode)
            if connection_result:
                # print the data
                print('{} is able to access {}:'.format(snode.searchable_name(), dnode.searchable_name()))
                for edge in path:
                    print('   {}'.format(edge.describe_edge()))
                print()

def write_connected_results(graph: Graph, source_nodes: List[Node], dest_nodes: List[Node], skip_admins: bool = False,
                            output: io.StringIO = os.devnull) -> None:
    """Handles a `connected` query and writes the results to output"""
    for snode in source_nodes:
        if skip_admins and snode.is_admin:
            continue

        for dnode in dest_nodes:
            connection_result, path = is_connected(graph, snode, dnode)
            if connection_result:
                # print the data
                output.write('{} is able to access {}:\n'.format(snode.searchable_name(), dnode.searchable_name()))
                for edge in path:
                    output.write('   {}\n'.format(edge.describe_edge()))

def is_connected(graph: Graph, source_node: Node, dest_node: Node) -> (bool, List[Edge]):
    """Method for determining if a source node can reach a destination node through edges. The return value is a
    bool, List[Edge] tuple indicating if there's a connection and the path the source node would need to take.
    """
    edge_lists = get_search_list(graph, source_node)
    for edge_list in edge_lists:
        final_node = edge_list[-1].destination
        if final_node == dest_node:
            return True, edge_list

    return False, None

def process_arguments(parsed_args: Namespace):
    """Given a namespace object generated from parsing args, perform the appropriate tasks. Returns an int
    matching expectations set by /usr/include/sysexits.h for command-line utilities."""

    if parsed_args.picked_graph_cmd == 'create':
        logger.debug('Called create subcommand of graph')

        # filter the args first
        if parsed_args.account is not None:
            print('Cannot specify offline-mode param `--account` when calling `pmapper graph create`. If you have '
                  'credentials for a specific account to graph, you can use those credentials similar to how the '
                  'AWS CLI works (environment variables, profiles, EC2 instance metadata). In the case of using '
                  'a profile, use the `--profile [PROFILE]` argument before specifying the `graph` subcommand.')
            return 64

        service_list_base = list(checker_map.keys())
        if parsed_args.include_services is not None:
            service_list = [x for x in service_list_base if x in parsed_args.include_services]
        elif parsed_args.exclude_services is not None:
            service_list = [x for x in service_list_base if x not in parsed_args.exclude_services]
        else:
            service_list = service_list_base
        logger.debug('Service list after processing args: {}'.format(service_list))

        # need to know account ID to search potential SCPs
        if parsed_args.localstack_endpoint is not None:
            session = botocore_tools.get_session(parsed_args.profile, {'endpoint_url': parsed_args.localstack_endpoint})
        else:
            session = botocore_tools.get_session(parsed_args.profile)

        scps = None
        if not parsed_args.ignore_orgs:
            if parsed_args.localstack_endpoint is not None:
                stsclient = session.create_client('sts', endpoint_url=parsed_args.localstack_endpoint)
            else:
                stsclient = session.create_client('sts')
            caller_identity = stsclient.get_caller_identity()
            caller_account = caller_identity['Account']
            logger.debug("Caller Identity: {}".format(caller_identity))

            org_tree_search_dir = Path(get_storage_root())
            org_id_pattern = re.compile(r'/o-\w+')
            for subdir in org_tree_search_dir.iterdir():
                if org_id_pattern.search(str(subdir)) is not None:
                    logger.debug('Checking {} to see if account {} is a member'.format(str(subdir), caller_account))
                    org_tree = OrganizationTree.create_from_dir(str(subdir))
                    if caller_account in org_tree.accounts:
                        logger.info('Account {} is a member of Organization {}'.format(caller_account, org_tree.org_id))
                        if caller_account == org_tree.management_account_id:
                            logger.info('Account {} is the management account, SCPs do not apply'.format(caller_account))
                        else:
                            logger.info('Identifying and applying SCPs for the graphing process')
                            scps = query_orgs.produce_scp_list_by_account_id(caller_account, org_tree)
                        break

        if parsed_args.localstack_endpoint is not None:
            full_service_list = ('autoscaling', 'cloudformation', 'codebuild', 'ec2', 'iam', 'kms', 'lambda',
                                 'sagemaker', 's3', 'ssm', 'secretsmanager', 'sns', 'sts', 'sqs')

            client_args_map = {
                x: {'endpoint_url': parsed_args.localstack_endpoint} for x in full_service_list
            }
        else:
            client_args_map = None

        graph = graph_actions.create_new_graph(session, service_list, parsed_args.include_regions,
                                               parsed_args.exclude_regions, scps, client_args_map)
        graph_actions.print_graph_data(graph)
        graph.store_graph_as_json(os.path.join(get_storage_root(), graph.metadata['account_id']))

    elif parsed_args.picked_graph_cmd == 'display':
        if parsed_args.account is None:
            session = botocore_tools.get_session(parsed_args.profile)
        else:
            session = None

        graph = graph_actions.get_existing_graph(
            session,
            parsed_args.account
        )
        graph_actions.print_graph_data(graph)

    elif parsed_args.picked_graph_cmd == 'list':
        print("Account IDs:")
        print("---")
        storage_root = Path(get_storage_root())
        account_id_pattern = re.compile(r'\d{12}')
        for direct in storage_root.iterdir():
            if account_id_pattern.search(str(direct)) is not None:
                metadata_file = direct.joinpath(Path('metadata.json'))
                with open(str(metadata_file)) as fd:
                    account_metadata = json.load(fd)
                version = account_metadata['pmapper_version']
                print("{} (PMapper Version {})".format(direct.name, version))

    return 0

def get_default_graph_path(account_or_org: str):
    """Returns a path to a given account or organization by the provided string."""
    return os.path.join(get_storage_root(), account_or_org)

